import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SocialBurstProps = Record<string, any>;

// Icon Path Data
const HEART_PATH = "M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z";
const THUMB_PATH = "M1 21h4V9H1v12zm22-11c0-1.1-.9-2-2-2h-6.31l.95-4.57.03-.32c0-.41-.17-.79-.44-1.06L14.17 1 7.59 7.59C7.22 7.95 7 8.45 7 9v10c0 1.1.9 2 2 2h9c.83 0 1.54-.5 1.84-1.22l3.02-7.05c.09-.23.14-.47.14-.73v-1.91l-.01-.01L23 10z";
// Eye split into two parts: Sclera (Outer) and Iris/Pupil (Inner)
const EYE_OUTER_PATH = "M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5z";
const EYE_PUPIL_PATH = "M12 9c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z";

interface Particle {
  id: number;
  type: "heart" | "thumb" | "eye";
  x: number;
  y: number;
  scale: number;
  rotation: number;
  delay: number;
  driftX: number;
  driftY: number;
}

const SocialBurst: React.FC<SocialBurstProps> = ({
  backgroundColor = "#f5f5f5",
  transparentBackground = false,
  durationInSeconds = 5,
  thumbsUpColor = "#2979FF",
  heartColor = "#FF1744",
  eyeColor = "#212121",
  iconCount = 150, // Increased default for "way more" icons
  scatterSpread = 1.0,
}) => {
  useFontLoader(["Inter"]); // Basic font load for protocol compliance

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate deterministic particles
  const particles = useMemo(() => {
    const items: Particle[] = [];
    const seed = 8823; 

    for (let i = 0; i < iconCount; i++) {
      const typeRand = random(seed + i);
      let type: "heart" | "thumb" | "eye" = "heart";
      if (typeRand > 0.33) type = "thumb";
      if (typeRand > 0.66) type = "eye";

      // Centered Gaussian-like distribution roughly
      const r1 = random(seed + i + 100);
      const r2 = random(seed + i + 200);
      
      // Map 0-1 to screen coordinates with spread factor
      const cx = width / 2;
      const cy = height / 2;
      
      // Adjusted multipliers to heavily focus on the middle 3rd
      // Y multiplier significantly reduced (0.5) to keep icons in the vertical center band
      const x = cx + (r1 - 0.5) * width * scatterSpread * 1.2;
      const y = cy + (r2 - 0.5) * height * scatterSpread * 0.5;

      const scale = 0.5 + random(seed + i + 300) * 1.2; // 0.5 to 1.7
      const rotation = (random(seed + i + 400) - 0.5) * 60; // -30 to 30 deg
      const delay = random(seed + i + 500) * 25; // 0 to 25 frames start delay

      const driftAngle = random(seed + i + 600) * Math.PI * 2;
      const driftSpeed = 30 + random(seed + i + 700) * 50;
      
      items.push({
        id: i,
        type,
        x,
        y,
        scale,
        rotation,
        delay,
        driftX: Math.cos(driftAngle) * driftSpeed,
        driftY: Math.sin(driftAngle) * driftSpeed - 30, // Slight upward bias
      });
    }
    return items;
  }, [iconCount, scatterSpread, width, height]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {particles.map((p) => {
        // Individual Particle Animation
        const activeFrame = frame - p.delay;
        
        // Elastic Pop Entrance
        const pop = spring({
          frame: activeFrame,
          fps,
          config: {
            damping: 12,
            stiffness: 180,
            mass: 0.6,
          },
        });

        // Drift over time
        const driftProgress = interpolate(
          activeFrame,
          [0, fps * durationInSeconds],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "extend" }
        );

        const currentX = p.x + p.driftX * driftProgress;
        const currentY = p.y + p.driftY * driftProgress;

        // Ensure we don't render before start
        if (activeFrame < 0) return null;

        // Specific Eye Animation (Wobble/Blink)
        let eyeTransform = "";
        let pupilTransform = "";
        if (p.type === "eye") {
           // Random blink every ~2 seconds based on ID
           const blinkCycle = (frame + p.id * 10) % 60; 
           const isBlinking = blinkCycle < 5; // 5 frames closed
           const eyeScaleY = isBlinking ? 0.1 : 1;
           eyeTransform = `scaleY(${eyeScaleY})`;

           // Pupil wandering
           const lookX = Math.sin(frame / 15 + p.id) * 2;
           const lookY = Math.cos(frame / 20 + p.id) * 2;
           pupilTransform = `translate(${lookX}px, ${lookY}px)`;
        }

        const baseSize = 60 * p.scale;

        return (
          <div
            key={p.id}
            style={{
              position: "absolute",
              left: currentX,
              top: currentY,
              width: baseSize,
              height: baseSize,
              transform: `translate(-50%, -50%) scale(${pop}) rotate(${p.rotation}deg)`,
              opacity: interpolate(activeFrame, [fps * durationInSeconds - 15, fps * durationInSeconds], [1, 0]),
            }}
          >
            <svg
              viewBox="0 0 24 24"
              width="100%"
              height="100%"
              style={{ overflow: "visible" }}
            >
              {p.type === "heart" && (
                <path
                  d={HEART_PATH}
                  fill={heartColor}
                  stroke="white"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              )}
              {p.type === "thumb" && (
                <path
                  d={THUMB_PATH}
                  fill={thumbsUpColor}
                  stroke="white"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              )}
              {p.type === "eye" && (
                <g style={{ transformOrigin: "center", transform: eyeTransform }}>
                  <path
                    d={EYE_OUTER_PATH}
                    fill="white"
                    stroke={eyeColor}
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                  <path
                    d={EYE_PUPIL_PATH}
                    fill={eyeColor}
                    style={{ transformOrigin: "center", transform: pupilTransform }}
                  />
                </g>
              )}
            </svg>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default SocialBurst;